class RiverLongJoinTest{public static void main(String[]a){int n=256;var e=new EnvironmentMap(EnvironmentMap.filled(n*n,300));e.water=EnvironmentMap.filled(n*n,62);e.river=new float[n*n];for(int x=20;x<236;x++){int i=128*n+x;e.water[i]=x<128?90:180;e.height[i]=e.water[i]-4;e.river[i]=1;}RiverBanks.finishChannels(e,n,62,5);for(int x=21;x<236;x++){int i=128*n+x;if(Math.abs(e.waterY(i,62)-e.waterY(i-1,62))>1||Math.abs(e.water[i]-e.height[i]-4)>.001)throw new AssertionError("Long tributary join failed");}System.out.println("PASS: large tributary elevation mismatch converges across entire reach, moving bed and water together");}}
